"""Builds the research-style report (PDF, Russian) about how the WetlandEar model was built and trained.
Numbers come from metrics JSON and logs; code listings are cut from the real files; figures from make_figures.py.
Usage:  python build_paper.py   (env: METRICS=path, VERSION=v5, OUT=path)"""
import json, os, datetime, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from paper_lib import *

BASE = r'C:\Users\Timur\Documents\wetlandear-models'
APP = r'C:\Users\Timur\Documents\wetlandear-app'
METRICS = os.environ.get('METRICS', BASE + r'\backup_v5\metrics_v5.json')
VER = os.environ.get('VERSION', 'v5')
OUT = os.environ.get('OUT', os.path.join(HERE, 'WetlandEar_research_report.pdf'))
M = json.load(open(METRICS, encoding='utf-8'))
ST = json.load(open(os.path.join(HERE, 'figs', 'stats.json'), encoding='utf-8'))
R = M['robustness']['summary']
pc = lambda x: ('%.1f' % (x * 100)).replace('.', ',') + '%'
n_spp, n_rec, n_win, n_nwin = M['species'], M['recordings'], M['windows'], M['noisy_windows']
acc_bn, acc_we, acc_rec = M['window_accuracy']['birdnet'], M['window_accuracy']['wetlandear'], M['recording_accuracy']
PS = M['per_species']
MASK = set(json.load(open(os.path.join(HERE, 'figs', 'masked.json'), encoding='utf-8'))) if os.path.exists(os.path.join(HERE, 'figs', 'masked.json')) else set()


def bn_cell(r, absent='нет в BirdNET'):
    if not r['in_birdnet']: return absent
    if r['sci'] in MASK: return '0,0%*'
    return pc(r['birdnet'])


buckets = [('90% и выше', lambda a: a >= .9), ('70–90%', lambda a: .7 <= a < .9), ('50–70%', lambda a: .5 <= a < .7), ('ниже 50%', lambda a: a < .5)]
bcount = [sum(1 for r in PS if f(r['head'])) for _, f in buckets]
few = sorted([r for r in PS if r['recordings'] < 15], key=lambda r: r['head'])
NF = lambda x: '{:,}'.format(x).replace(',', '\u00a0')

doc = Doc(OUT, title='WetlandEar: как построена и обучена система распознавания птиц', author='Проект WetlandEar', subject='Технический отчёт')
story = []
A_ = story.append


def E_(x):
    """Accept either one flowable or a list of them."""
    if isinstance(x, (list, tuple)): story.extend(x)
    else: story.append(x)

