A_(Paragraph('<font name="DVM">z_k = w_k · x + b_k,    p_k = exp(z_k) / Σ_j exp(z_j)</font>', ParagraphStyle('f', parent=S['body'], alignment=TA_CENTER, spaceBefore=4, spaceAfter=6)))
